setup/nginx.conf<pre><code># Bottleneck: balanceamento de carga.
# O Nginx é o único serviço exposto (porta 8080 do host). Ele distribui as
# requisições entre as réplicas do gateway (round robin, o padrão do upstream).

user  nginx;
worker_processes  auto;

error_log  /var/log/nginx/error.log notice;
pid        /run/nginx.pid;

events {
    worker_connections  1024;
}

http {

    # DNS interno do Docker: com "resolve" (nginx &gt;= 1.27.3) o upstream é
    # re-resolvido a cada 10 s, então "docker compose up --scale gateway=N"
    # entra no balanceamento sem precisar de nginx -s reload
    resolver 127.0.0.11 valid=10s ipv6=off;

    upstream gateways {
        zone gateways 64k;
        server gateway:8080 resolve;
        # conexões reaproveitadas com o gateway (menos handshakes sob carga)
        keepalive 32;
    }

    log_format upstream '$remote_addr "$request" $status -&gt; $upstream_addr ($upstream_response_time s)';
    access_log /var/log/nginx/access.log upstream;

    server {
        listen 80;
        server_tokens off;

        # métricas e detalhes do actuator ficam só na rede interna
        # (o Prometheus fala direto com o gateway); o health fica público
        location = /gateway/actuator/health {
            proxy_pass http://gateways;
        }
        location /gateway/actuator {
            return 404;
        }

        location / {
            proxy_pass         http://gateways;
            proxy_http_version 1.1;
            proxy_set_header   Connection        "";
            proxy_set_header   Host              $host;
            proxy_set_header   X-Real-IP         $remote_addr;
            proxy_set_header   X-Forwarded-For   $proxy_add_x_forwarded_for;
            proxy_set_header   X-Forwarded-Proto $scheme;
        }
    }
}
